CREATE TABLE public.crm_members (user_id uuid primary key, role text not null default 'staff' check (role in ('admin','manager','staff')), created_at timestamptz default now());
GRANT SELECT ON public.crm_members TO authenticated; GRANT ALL ON public.crm_members TO service_role;
ALTER TABLE public.crm_members ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.is_crm_member() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.crm_members WHERE user_id=auth.uid()) $$;
GRANT EXECUTE ON FUNCTION public.is_crm_member() TO authenticated;
CREATE POLICY crm_member_select ON public.crm_members FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE TABLE public.crm_companies (id uuid primary key default gen_random_uuid(), name text not null, industry text, phone text, email text, website text, location text, status text default 'Prospect', notes text, created_by uuid, created_at timestamptz default now(), updated_at timestamptz default now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.crm_companies TO authenticated; GRANT ALL ON public.crm_companies TO service_role; ALTER TABLE public.crm_companies ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.crm_contacts (id uuid primary key default gen_random_uuid(), company_id uuid references public.crm_companies(id) on delete cascade, name text not null, role text, phone text, email text, preferred_channel text, created_by uuid, created_at timestamptz default now(), updated_at timestamptz default now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.crm_contacts TO authenticated; GRANT ALL ON public.crm_contacts TO service_role; ALTER TABLE public.crm_contacts ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.crm_campaigns (id uuid primary key default gen_random_uuid(), name text not null, channel text, status text default 'Draft', budget numeric default 0, leads integer default 0, qualified integer default 0, revenue numeric default 0, start_date date, end_date date, created_by uuid, created_at timestamptz default now(), updated_at timestamptz default now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.crm_campaigns TO authenticated; GRANT ALL ON public.crm_campaigns TO service_role; ALTER TABLE public.crm_campaigns ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.crm_leads (id uuid primary key default gen_random_uuid(), name text not null, company text, email text, phone text, status text default 'New', source text, campaign_id uuid references public.crm_campaigns(id) on delete set null, company_id uuid references public.crm_companies(id) on delete set null, owner_id uuid, value numeric default 0, notes text, created_at timestamptz default now(), updated_at timestamptz default now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.crm_leads TO authenticated; GRANT ALL ON public.crm_leads TO service_role; ALTER TABLE public.crm_leads ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.crm_deals (id uuid primary key default gen_random_uuid(), company_id uuid references public.crm_companies(id) on delete set null, name text not null, value numeric default 0, stage text default 'New', expected_close date, service text, owner_id uuid, created_at timestamptz default now(), updated_at timestamptz default now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.crm_deals TO authenticated; GRANT ALL ON public.crm_deals TO service_role; ALTER TABLE public.crm_deals ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.crm_tasks (id uuid primary key default gen_random_uuid(), title text not null, description text, due_date timestamptz, priority text default 'Medium', completed boolean default false, lead_id uuid references public.crm_leads(id) on delete cascade, company_id uuid references public.crm_companies(id) on delete cascade, deal_id uuid references public.crm_deals(id) on delete cascade, assigned_to uuid, created_by uuid, created_at timestamptz default now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.crm_tasks TO authenticated; GRANT ALL ON public.crm_tasks TO service_role; ALTER TABLE public.crm_tasks ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.crm_activities (id uuid primary key default gen_random_uuid(), type text not null, title text not null, body text, lead_id uuid references public.crm_leads(id) on delete cascade, company_id uuid references public.crm_companies(id) on delete cascade, contact_id uuid references public.crm_contacts(id) on delete cascade, deal_id uuid references public.crm_deals(id) on delete cascade, created_by uuid, created_at timestamptz default now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.crm_activities TO authenticated; GRANT ALL ON public.crm_activities TO service_role; ALTER TABLE public.crm_activities ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.crm_messages (id uuid primary key default gen_random_uuid(), company_id uuid references public.crm_companies(id) on delete cascade, contact_id uuid references public.crm_contacts(id) on delete set null, channel text not null, direction text not null, subject text, body text not null, read boolean default false, created_by uuid, created_at timestamptz default now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.crm_messages TO authenticated; GRANT ALL ON public.crm_messages TO service_role; ALTER TABLE public.crm_messages ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.crm_projects (id uuid primary key default gen_random_uuid(), company_id uuid references public.crm_companies(id) on delete cascade, deal_id uuid references public.crm_deals(id) on delete set null, name text not null, service text, status text default 'Not Started', start_date date, due_date date, progress integer default 0, owner_id uuid, created_at timestamptz default now(), updated_at timestamptz default now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.crm_projects TO authenticated; GRANT ALL ON public.crm_projects TO service_role; ALTER TABLE public.crm_projects ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.crm_project_deliverables (id uuid primary key default gen_random_uuid(), project_id uuid not null references public.crm_projects(id) on delete cascade, title text not null, description text, status text default 'Pending', due_date date, created_at timestamptz default now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.crm_project_deliverables TO authenticated; GRANT ALL ON public.crm_project_deliverables TO service_role; ALTER TABLE public.crm_project_deliverables ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.crm_quotes (id uuid primary key default gen_random_uuid(), company_id uuid references public.crm_companies(id) on delete cascade, deal_id uuid references public.crm_deals(id) on delete set null, number text not null unique, title text not null, amount numeric default 0, status text default 'Draft', valid_until date, created_at timestamptz default now(), updated_at timestamptz default now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.crm_quotes TO authenticated; GRANT ALL ON public.crm_quotes TO service_role; ALTER TABLE public.crm_quotes ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.crm_invoices (id uuid primary key default gen_random_uuid(), company_id uuid references public.crm_companies(id) on delete cascade, project_id uuid references public.crm_projects(id) on delete set null, number text not null unique, amount numeric default 0, paid numeric default 0, status text default 'Draft', due_date date, created_at timestamptz default now(), updated_at timestamptz default now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.crm_invoices TO authenticated; GRANT ALL ON public.crm_invoices TO service_role; ALTER TABLE public.crm_invoices ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.crm_payments (id uuid primary key default gen_random_uuid(), invoice_id uuid not null references public.crm_invoices(id) on delete cascade, company_id uuid references public.crm_companies(id) on delete cascade, amount numeric not null, method text not null, reference text, date date default current_date, created_by uuid, created_at timestamptz default now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.crm_payments TO authenticated; GRANT ALL ON public.crm_payments TO service_role; ALTER TABLE public.crm_payments ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.crm_automations (id uuid primary key default gen_random_uuid(), name text not null, trigger text not null, action text not null, active boolean default true, runs integer default 0, created_by uuid, created_at timestamptz default now(), updated_at timestamptz default now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.crm_automations TO authenticated; GRANT ALL ON public.crm_automations TO service_role; ALTER TABLE public.crm_automations ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.crm_workflows (id uuid primary key default gen_random_uuid(), name text not null, description text, active boolean default true, created_by uuid, created_at timestamptz default now(), updated_at timestamptz default now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.crm_workflows TO authenticated; GRANT ALL ON public.crm_workflows TO service_role; ALTER TABLE public.crm_workflows ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.crm_workflow_steps (id uuid primary key default gen_random_uuid(), workflow_id uuid not null references public.crm_workflows(id) on delete cascade, position integer not null, title text not null, description text, unique(workflow_id,position));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.crm_workflow_steps TO authenticated; GRANT ALL ON public.crm_workflow_steps TO service_role; ALTER TABLE public.crm_workflow_steps ENABLE ROW LEVEL SECURITY;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['crm_companies','crm_contacts','crm_campaigns','crm_leads','crm_deals','crm_tasks','crm_activities','crm_messages','crm_projects','crm_project_deliverables','crm_quotes','crm_invoices','crm_payments','crm_automations','crm_workflows','crm_workflow_steps'] LOOP EXECUTE format('CREATE POLICY crm_read ON public.%I FOR SELECT TO authenticated USING (public.is_crm_member())',t); EXECUTE format('CREATE POLICY crm_insert ON public.%I FOR INSERT TO authenticated WITH CHECK (public.is_crm_member())',t); EXECUTE format('CREATE POLICY crm_update ON public.%I FOR UPDATE TO authenticated USING (public.is_crm_member()) WITH CHECK (public.is_crm_member())',t); EXECUTE format('CREATE POLICY crm_delete ON public.%I FOR DELETE TO authenticated USING (public.is_crm_member())',t); END LOOP; END $$;